<pre><code>function isSequential($value){
    if(is_array($value) || ($value instanceof \Countable &amp;&amp; $value instanceof \ArrayAccess)){
        for ($i = count($value) - 1; $i &gt;= 0; $i--) {
            if (!isset($value[$i]) &amp;&amp; !array_key_exists($i, $value)) {
                return false;
            }
        }
        return true;
